import { Order } from '../../domain/order/Order';
import { OrderStatus } from '../../domain/order/OrderStatus';

export interface OrderLineDto {
  readonly productId: string;
  readonly quantity: number;
  readonly unitPriceCents: number;
  readonly lineTotalCents: number;
}

export interface OrderDto {
  readonly id: string;
  readonly customerId: string;
  readonly status: OrderStatus;
  readonly lines: readonly OrderLineDto[];
  readonly totalCents: number;
  readonly history: ReadonlyArray<{ status: OrderStatus; at: string }>;
}

export function toOrderDto(order: Order): OrderDto {
  return {
    id: order.id,
    customerId: order.customerId,
    status: order.status,
    lines: order.lines.map((line) => ({
      productId: line.productId,
      quantity: line.quantity.value,
      unitPriceCents: line.unitPrice.cents,
      lineTotalCents: line.lineTotal.cents,
    })),
    totalCents: order.total.cents,
    history: order.history.map((change) => ({ status: change.status, at: change.at.toISOString() })),
  };
}

